class BroadcastPage extends StatefulWidget{const BroadcastPage({super.key,required this.controller});final AppController controller;@override State<BroadcastPage> createState()=>_BroadcastPageState();}
class _BroadcastPageState extends State<BroadcastPage>{
  @override Widget build(BuildContext context){final items=widget.controller.broadcasts.where((e)=>e.kind=='manual').toList();return Scaffold(backgroundColor:Colors.transparent,appBar:AppBar(title:const Text('إرسال للمجموعات'),backgroundColor:Colors.transparent,actions:[IconButton(onPressed:widget.controller.refreshBroadcasts,icon:const Icon(Icons.refresh_rounded))]),floatingActionButton:FloatingActionButton.extended(onPressed:_compose,icon:const Icon(Icons.campaign_rounded),label:const Text('إرسال جديد')),body:RefreshIndicator(onRefresh:widget.controller.refreshBroadcasts,child:items.isEmpty?ListView(padding:const EdgeInsets.all(24),children:const[SizedBox(height:110),Icon(Icons.campaign_outlined,size:64),SizedBox(height:18),Text('لا يوجد سجل إرسال جماعي بعد.',textAlign:TextAlign.center),SizedBox(height:8),Text('أنشئ رسالة، اختر جميع المجموعات أو مجموعات محددة، راجعها ثم أرسل.',textAlign:TextAlign.center)]):ListView.separated(padding:const EdgeInsets.fromLTRB(16,8,16,90),itemCount:items.length,separatorBuilder:(_,_)=>const SizedBox(height:10),itemBuilder:(context,index){final e=items[index];return Card(child:ListTile(onTap:()=>_openReport(e.id),leading:CircleAvatar(child:Icon(_statusIcon(e.status))),title:Text('إرسال #${e.id}',style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${_statusLabel(e.status)} • ${e.sentCount}/${e.targetCount} نجح${e.failedCount>0?' • ${e.failedCount} فشل':''}\n${e.content.summary}',maxLines:3,overflow:TextOverflow.ellipsis)));})));}
  Future<void> _compose()async{final d=await Navigator.push<ApiBroadcast>(context,MaterialPageRoute(builder:(_)=>BroadcastWizardPage(controller:widget.controller)));if(d!=null){await widget.controller.refreshBroadcasts();if(mounted)await _openReport(d.id);}}
  Future<void> _openReport(int id)async{await Navigator.push<void>(context,MaterialPageRoute(builder:(_)=>BroadcastReportPage(controller:widget.controller,broadcastId:id)));await widget.controller.refreshBroadcasts();}
}

class BroadcastWizardPage extends StatefulWidget{const BroadcastWizardPage({super.key,required this.controller});final AppController controller;@override State<BroadcastWizardPage> createState()=>_BroadcastWizardPageState();}
class _BroadcastWizardPageState extends State<BroadcastWizardPage>{ApiMessageContent _content=const ApiMessageContent(components:[]);String _targetMode='all';Set<int> _groupIds={};int _step=0;bool _sending=false;
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('إرسال جديد للمجموعات')),body:Stepper(currentStep:_step,onStepTapped:(v)=>setState(()=>_step=v),onStepContinue:_sending?null:_continue,onStepCancel:_sending||_step==0?null:()=>setState(()=>_step--),controlsBuilder:(context,d)=>Padding(padding:const EdgeInsets.only(top:18),child:Row(children:[FilledButton.icon(onPressed:d.onStepContinue,icon:Icon(_step==2?Icons.send_rounded:Icons.arrow_forward_rounded),label:Text(_step==2?'إرسال الآن':'التالي')),if(_step>0)...[const SizedBox(width:8),TextButton(onPressed:d.onStepCancel,child:const Text('السابق'))]])),steps:[Step(title:const Text('1. المحتوى'),isActive:_step>=0,content:ContentComposer(controller:widget.controller,value:_content,onChanged:(v)=>setState(()=>_content=v),title:'الرسالة التي ستصل للمجموعات')),Step(title:const Text('2. المستهدفون'),isActive:_step>=1,content:GroupSelector(groups:widget.controller.groups,mode:_targetMode,selectedIds:_groupIds,onModeChanged:(v)=>setState((){_targetMode=v;if(v=='all')_groupIds.clear();}),onSelectionChanged:(v)=>setState(()=>_groupIds=v))),Step(title:const Text('3. المراجعة والإرسال'),isActive:_step>=2,content:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[ListTile(contentPadding:EdgeInsets.zero,title:const Text('المستهدفون'),trailing:Text(_targetMode=='all'?'جميع المجموعات المعتمدة':'${_groupIds.length} مجموعة',style:const TextStyle(fontWeight:FontWeight.bold))),const SizedBox(height:8),const Text('المحتوى',style:TextStyle(fontWeight:FontWeight.bold)),Card(child:Padding(padding:const EdgeInsets.all(14),child:Text(_content.summary))),const SizedBox(height:10),const Card(child:Padding(padding:EdgeInsets.all(14),child:Text('سيتم الإرسال للمجموعات بشكل متسلسل عبر طابور الإرسال، وستظهر نتيجة كل مجموعة في التقرير.'))),if(_sending)const Padding(padding:EdgeInsets.only(top:12),child:LinearProgressIndicator())]))]));
  Future<void> _continue()async{if(_step==0&&_content.isEmpty)return _msg('أضف محتوى الرسالة أولًا.');if(_step==1&&_targetMode=='selected'&&_groupIds.isEmpty)return _msg('اختر مجموعة واحدة على الأقل.');if(_step<2){setState(()=>_step++);return;}setState(()=>_sending=true);try{final d=await widget.controller.api.createBroadcast(content:_content,targetMode:_targetMode,groupIds:_groupIds.toList());if(mounted)Navigator.pop(context,d);}catch(e){_msg('تعذر بدء الإرسال: $e');}finally{if(mounted)setState(()=>_sending=false);}}void _msg(String t){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(t)));}
