class BroadcastReportPage extends StatefulWidget{const BroadcastReportPage({super.key,required this.controller,required this.broadcastId});final AppController controller;final int broadcastId;@override State<BroadcastReportPage> createState()=>_BroadcastReportPageState();}
class _BroadcastReportPageState extends State<BroadcastReportPage>{ApiBroadcast? _item;Timer? _timer;bool _loading=true;@override void initState(){super.initState();_load();_timer=Timer.periodic(const Duration(seconds:2),(_){final s=_item?.status;if(s=='queued'||s=='running')_load(silent:true);});}@override void dispose(){_timer?.cancel();super.dispose();}Future<void> _load({bool silent=false})async{if(!silent&&mounted)setState(()=>_loading=true);try{_item=await widget.controller.api.getBroadcast(widget.broadcastId);}catch(e){if(mounted&&!silent)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تعذر تحميل التقرير: $e')));}finally{if(mounted)setState(()=>_loading=false);}}
