  Widget _metric(String l,int v)=>Column(children:[Text('$v',style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),Text(l)]);Future<void> _retry()async{await widget.controller.api.retryBroadcast(widget.broadcastId);await _load();}Future<void> _cancel()async{await widget.controller.api.cancelBroadcast(widget.broadcastId);await _load();}
}
IconData _statusIcon(String s)=>switch(s){'completed'||'sent'=>Icons.check_circle_rounded,'failed'=>Icons.error_rounded,'cancelled'=>Icons.cancel_rounded,'running'||'sending'=>Icons.sync_rounded,'queued'||'pending'=>Icons.schedule_rounded,_=>Icons.info_outline_rounded};String _statusLabel(String s)=>switch(s){'completed'=>'مكتمل','sent'=>'تم الإرسال','failed'=>'فشل','cancelled'=>'ملغي','running'||'sending'=>'جاري الإرسال','queued'=>'في الطابور','pending'=>'بانتظار الإرسال',_=>s};
